 internal static float Root(string id,float clock,bool loop){float[][] r;if(!Roots.TryGetValue(id,out r))return 0;float[] t=r[0],x=r[1];float offset=0;if(loop&&t[t.Length-1]>0){int cycles=(int)(clock/t[t.Length-1]);offset=cycles*x[x.Length-1];clock%=t[t.Length-1];}if(clock<=0)return offset;if(clock>=t[t.Length-1])return offset+x[x.Length-1];int i=1;while(t[i]<clock)i++;return offset+x[i-1]+(x[i]-x[i-1])*(clock-t[i-1])/(t[i]-t[i-1]);}
